     1→/**
     2→ * BlockDiagramView - SVG-based processor block diagram visualization
     3→ *
     4→ * Renders a hardware-accurate 5-stage pipelined RISC processor architecture
     5→ * showing Instruction Memory, Register File, ALU, Data Memory, pipeline registers,
     6→ * multiplexers, PC, and data path connections.
     7→ *
     8→ * Components highlight based on active pipeline stages. Pipeline registers display
     9→ * current instruction names. Tooltips provide component descriptions.
    10→ *
    11→ * Usage:
    12→ *   const view = new BlockDiagramView(containerElement);
    13→ *   view.render(cpuState);
    14→ */
    15→(function() {
    16→  'use strict';
    17→
    18→  const SVG_NS = 'http://www.w3.org/2000/svg';
    19→
    20→  class BlockDiagramView {
    21→    /**
    22→     * Creates a BlockDiagramView instance
    23→     * @param {HTMLElement} container - DOM element to render SVG diagram into
    24→     */
    25→    constructor(container) {
    26→      this.container = container;
    27→      this.svg = null;
    28→      this.componentMap = new Map();  // Fast component lookup by data-component attribute
    29→      this.initializeDiagram();
    30→    }
    31→
    32→    /**
    33→     * Creates an SVG element with attributes
    34→     * @param {string} tagName - SVG element tag name
    35→     * @param {object} attributes - Attribute key-value pairs
    36→     * @returns {SVGElement} Created SVG element
    37→     * @private
    38→     */
    39→    _svg(tagName, attributes = {}) {
    40→      const element = document.createElementNS(SVG_NS, tagName);
    41→      Object.entries(attributes).forEach(([key, value]) => {
    42→        element.setAttribute(key, value);
    43→      });
    44→      return element;
    45→    }
    46→
    47→    /**
    48→     * Initializes the complete SVG block diagram
    49→     * Creates all components in painter's order (back to front)
    50→     * @private
    51→     */
    52→    initializeDiagram() {
    53→      // Create root SVG with responsive viewBox
    54→      this.svg = this._svg('svg', {
    55→        viewBox: '0 0 900 500',
    56→        preserveAspectRatio: 'xMidYMid meet',
    57→        class: 'cpu-block-diagram'
    58→      });
    59→
    60→      // Add stage labels (background layer)
    61→      this.svg.appendChild(this._createStageLabels());
    62→
    63→      // Add data path wires (background layer)
    64→      this.svg.appendChild(this._createDataPaths());
    65→
    66→      // Add hardware components (middle layer)
    67→      this.svg.appendChild(this._createIFStage());
    68→      this.svg.appendChild(this._createPipelineRegister('FD', 235, 'F/D', 'Fetch/Decode Register - Holds instruction between IF and ID stages'));
    69→      this.svg.appendChild(this._createIDStage());
    70→      this.svg.appendChild(this._createPipelineRegister('DX', 415, 'D/X', 'Decode/Execute Register - Holds decoded instruction and operands'));
    71→      this.svg.appendChild(this._createEXStage());
    72→      this.svg.appendChild(this._createPipelineRegister('XM', 575, 'X/M', 'Execute/Memory Register - Holds ALU result and write data'));
    73→      this.svg.appendChild(this._createMEMStage());
    74→      this.svg.appendChild(this._createPipelineRegister('MW', 735, 'M/W', 'Memory/Writeback Register - Holds data for register write'));
    75→      this.svg.appendChild(this._createWBStage());
    76→
    77→      // Append to container
    78→      this.container.appendChild(this.svg);
    79→    }
    80→
    81→    /**
    82→     * Creates stage labels above each pipeline stage
    83→     * @returns {SVGGElement} Group containing stage labels
    84→     * @private
    85→     */
    86→    _createStageLabels() {
    87→      const g = this._svg('g', { class: 'stage-labels' });
    88→
    89→      const stages = [
    90→        { label: 'IF', x: 85 },
    91→        { label: 'ID', x: 315 },
    92→        { label: 'EX', x: 490 },
    93→        { label: 'MEM', x: 665 },
    94→        { label: 'WB', x: 820 }
    95→      ];
    96→
    97→      stages.forEach(({ label, x }) => {
    98→        const text = this._svg('text', {
    99→          x: x,
   100→          y: 30,
   101→          class: 'stage-label-text'
   102→        });
   103→        text.textContent = label;
   104→        g.appendChild(text);
   105→      });
   106→
   107→      return g;
   108→    }
   109→
   110→    /**
   111→     * Creates data path wires connecting components
   112→     * @returns {SVGGElement} Group containing all data path connections
   113→     * @private
   114→     */
   115→    _createDataPaths() {
   116→      const g = this._svg('g', { class: 'data-paths' });
   117→
   118→      // PC to Instruction Memory
   119→      g.appendChild(this._svg('line', {
   120→        x1: 80, y1: 240, x2: 100, y2: 240,
   121→        class: 'data-path'
   122→      }));
   123→
   124→      // Instruction Memory to F/D register
   125→      g.appendChild(this._svg('line', {
   126→        x1: 220, y1: 240, x2: 235, y2: 240,
   127→        class: 'data-path'
   128→      }));
   129→
   130→      // F/D to Register File (instruction decode)
   131→      g.appendChild(this._svg('line', {
   132→        x1: 243, y1: 200, x2: 270, y2: 200,
   133→        class: 'data-path'
   134→      }));
   135→
   136→      // F/D to Sign Extend
   137→      g.appendChild(this._svg('line', {
   138→        x1: 243, y1: 397, x2: 290, y2: 397,
   139→        class: 'data-path'
   140→      }));
   141→
   142→      // Register File to D/X register (read data)
   143→      g.appendChild(this._svg('line', {
   144→        x1: 390, y1: 220, x2: 415, y2: 220,
   145→        class: 'data-path'
   146→      }));
   147→
   148→      // Sign Extend to D/X register
   149→      g.appendChild(this._svg('line', {
   150→        x1: 370, y1: 397, x2: 415, y2: 397,
   151→        class: 'data-path'
   152→      }));
   153→
   154→      // D/X to ALU Src Mux
   155→      g.appendChild(this._svg('line', {
   156→        x1: 423, y1: 230, x2: 445, y2: 230,
   157→        class: 'data-path'
   158→      }));
   159→
   160→      // ALU Src Mux to ALU
   161→      g.appendChild(this._svg('line', {
   162→        x1: 460, y1: 230, x2: 480, y2: 230,
   163→        class: 'data-path'
   164→      }));
   165→
   166→      // ALU to X/M register
   167→      g.appendChild(this._svg('line', {
   168→        x1: 560, y1: 230, x2: 575, y2: 230,
   169→        class: 'data-path'
   170→      }));
   171→
   172→      // X/M to Data Memory (address)
   173→      g.appendChild(this._svg('line', {
   174→        x1: 583, y1: 220, x2: 610, y2: 220,
   175→        class: 'data-path'
   176→      }));
   177→
   178→      // X/M to Data Memory (write data)
   179→      g.appendChild(this._svg('line', {
   180→        x1: 583, y1: 250, x2: 610, y2: 250,
   181→        class: 'data-path'
   182→      }));
   183→
   184→      // Data Memory to M/W register
   185→      g.appendChild(this._svg('line', {
   186→        x1: 730, y1: 240, x2: 735, y2: 240,
   187→        class: 'data-path'
   188→      }));
   189→
   190→      // M/W to WB Mux
   191→      g.appendChild(this._svg('line', {
   192→        x1: 743, y1: 240, x2: 780, y2: 240,
   193→        class: 'data-path'
   194→      }));
   195→
   196→      // WB Mux to Register File (write back - long feedback line)
   197→      g.appendChild(this._svg('path', {
   198→        d: 'M 810 240 L 850 240 L 850 60 L 330 60 L 330 130',
   199→        class: 'data-path',
   200→        fill: 'none'
   201→      }));
   202→
   203→      // PC +4 feedback (Adder to PC)
   204→      g.appendChild(this._svg('path', {
   205→        d: 'M 50 310 L 50 330 L 10 330 L 10 210 L 20 210',
   206→        class: 'data-path',
   207→        fill: 'none'
   208→      }));
   209→
   210→      return g;
   211→    }
   212→
   213→    /**
   214→     * Creates IF (Instruction Fetch) stage components
   215→     * @returns {SVGGElement} Group containing PC, Adder, and Instruction Memory
   216→     * @private
   217→     */
   218→    _createIFStage() {
   219→      const g = this._svg('g', { class: 'stage-group if-stage' });
   220→
   221→      // PC block
   222→      const pc = this._createComponent('PC', 20, 220, 60, 40, 'PC', 'pc', 'Program Counter - Holds address of current instruction');
   223→      this.componentMap.set('PC', pc);
   224→      g.appendChild(pc);
   225→
   226→      // Adder (+4)
   227→      const adder = this._createComponent('ADDER', 20, 280, 60, 30, '+4', 'adder', 'Adder - Increments PC by 4 for next instruction');
   228→      this.componentMap.set('ADDER', adder);
   229→      g.appendChild(adder);
   230→
   231→      // Instruction Memory
   232→      const imem = this._createComponent('IMEM', 100, 150, 120, 180, null, 'instruction-memory', 'Instruction Memory - Stores program instructions');
   233→      // Multi-line label for Instruction Memory
   234→      const imemLabel = this._createMultiLineLabel(160, 240, ['Instruction', 'Memory']);
   235→      imem.appendChild(imemLabel);
   236→      this.componentMap.set('IMEM', imem);
   237→      g.appendChild(imem);
   238→
   239→      return g;
   240→    }
   241→
   242→    /**
   243→     * Creates ID (Instruction Decode) stage components
   244→     * @returns {SVGGElement} Group containing Register File and Sign Extend
   245→     * @private
   246→     */
   247→    _createIDStage() {
   248→      const g = this._svg('g', { class: 'stage-group id-stage' });
   249→
   250→      // Register File
   251→      const regfile = this._createComponent('REGFILE', 270, 130, 120, 220, null, 'register-file', 'Register File - 32 general-purpose registers');
   252→      const regfileLabel = this._createMultiLineLabel(330, 240, ['Register', 'File']);
   253→      regfile.appendChild(regfileLabel);
   254→      this.componentMap.set('REGFILE', regfile);
   255→      g.appendChild(regfile);
   256→
   257→      // Sign Extend
   258→      const signext = this._createComponent('SIGNEXT', 290, 380, 80, 35, null, 'sign-extend', 'Sign Extend - Extends 16-bit immediate to 32 bits');
   259→      const signextLabel = this._createMultiLineLabel(330, 397, ['Sign', 'Extend']);
   260→      signext.appendChild(signextLabel);
   261→      this.componentMap.set('SIGNEXT', signext);
   262→      g.appendChild(signext);
   263→
   264→      return g;
   265→    }
   266→
   267→    /**
   268→     * Creates EX (Execute) stage components
   269→     * @returns {SVGGElement} Group containing ALU and ALU Src Mux
   270→     * @private
   271→     */
   272→    _createEXStage() {
   273→      const g = this._svg('g', { class: 'stage-group ex-stage' });
   274→
   275→      // ALU Src Multiplexer (before ALU)
   276→      const aluMux = this._createMultiplexer('ALU_SRC', 445, 220, 'ALU Source MUX - Selects register value or immediate');
   277→      this.componentMap.set('ALU_SRC', aluMux);
   278→      g.appendChild(aluMux);
   279→
   280→      // ALU
   281→      const alu = this._createComponent('ALU', 480, 170, 80, 120, 'ALU', 'alu', 'Arithmetic Logic Unit - Performs computations (add, sub, and, or, etc.)');
   282→      this.componentMap.set('ALU', alu);
   283→      g.appendChild(alu);
   284→
   285→      return g;
   286→    }
   287→
   288→    /**
   289→     * Creates MEM (Memory Access) stage components
   290→     * @returns {SVGGElement} Group containing Data Memory
   291→     * @private
   292→     */
   293→    _createMEMStage() {
   294→      const g = this._svg('g', { class: 'stage-group mem-stage' });
   295→
   296→      // Data Memory
   297→      const dmem = this._createComponent('DMEM', 610, 150, 120, 180, null, 'data-memory', 'Data Memory - Read/write data storage for load/store instructions');
   298→      const dmemLabel = this._createMultiLineLabel(670, 240, ['Data', 'Memory']);
   299→      dmem.appendChild(dmemLabel);
   300→      this.componentMap.set('DMEM', dmem);
   301→      g.appendChild(dmem);
   302→
   303→      return g;
   304→    }
   305→
   306→    /**
   307→     * Creates WB (Write Back) stage components
   308→     * @returns {SVGGElement} Group containing WB Mux
   309→     * @private
   310→     */
   311→    _createWBStage() {
   312→      const g = this._svg('g', { class: 'stage-group wb-stage' });
   313→
   314→      // WB Multiplexer (select ALU result vs memory data)
   315→      const wbMux = this._createMultiplexer('WB_SRC', 780, 230, 'Writeback MUX - Selects ALU result or memory data for register write');
   316→      this.componentMap.set('WB_SRC', wbMux);
   317→      g.appendChild(wbMux);
   318→
   319→      return g;
   320→    }
   321→
   322→    /**
   323→     * Creates a hardware component (functional unit)
   324→     * @param {string} dataComponent - Component identifier for data-component attribute
   325→     * @param {number} x - X coordinate
   326→     * @param {number} y - Y coordinate
   327→     * @param {number} width - Component width
   328→     * @param {number} height - Component height
   329→     * @param {string|null} label - Single-line label (null for multi-line labels added separately)
   330→     * @param {string} className - CSS class name for component type
   331→     * @param {string} tooltip - Tooltip description
   332→     * @returns {SVGGElement} Component group
   333→     * @private
   334→     */
   335→    _createComponent(dataComponent, x, y, width, height, label, className, tooltip) {
   336→      const g = this._svg('g', {
   337→        class: `component ${className}`,
   338→        'data-component': dataComponent
   339→      });
   340→
   341→      // Tooltip
   342→      const title = this._svg('title');
   343→      title.textContent = tooltip;
   344→      g.appendChild(title);
   345→
   346→      // Background rectangle
   347→      const rect = this._svg('rect', {
   348→        x: x,
   349→        y: y,
   350→        width: width,
   351→        height: height,
   352→        rx: 4
   353→      });
   354→      g.appendChild(rect);
   355→
   356→      // Single-line label (if provided)
   357→      if (label) {
   358→        const text = this._svg('text', {
   359→          x: x + width / 2,
   360→          y: y + height / 2,
   361→          'text-anchor': 'middle',
   362→          'dominant-baseline': 'middle',
   363→          class: 'component-label'
   364→        });
   365→        text.textContent = label;
   366→        g.appendChild(text);
   367→      }
   368→
   369→      return g;
   370→    }
   371→
   372→    /**
   373→     * Creates a multi-line text label using tspan elements
   374→     * @param {number} x - X coordinate (center)
   375→     * @param {number} y - Y coordinate (center of all lines)
   376→     * @param {string[]} lines - Array of text lines
   377→     * @returns {SVGTextElement} Text element with tspan children
   378→     * @private
   379→     */
   380→    _createMultiLineLabel(x, y, lines) {
   381→      const lineHeight = 16;
   382→      const totalHeight = (lines.length - 1) * lineHeight;
   383→      const startY = y - totalHeight / 2;
   384→
   385→      const text = this._svg('text', {
   386→        x: x,
   387→        'text-anchor': 'middle',
   388→        class: 'component-label'
   389→      });
   390→
   391→      lines.forEach((line, index) => {
   392→        const tspan = this._svg('tspan', {
   393→          x: x,
   394→          y: startY + index * lineHeight,
   395→          'dominant-baseline': 'middle'
   396→        });
   397→        tspan.textContent = line;
   398→        text.appendChild(tspan);
   399→      });
   400→
   401→      return text;
   402→    }
   403→
   404→    /**
   405→     * Creates a multiplexer (blue triangle)
   406→     * @param {string} muxName - Mux identifier for data-mux attribute
   407→     * @param {number} x - Center X coordinate
   408→     * @param {number} y - Center Y coordinate
   409→     * @param {string} tooltip - Tooltip description
   410→     * @returns {SVGGElement} Multiplexer group
   411→     * @private
   412→     */
   413→    _createMultiplexer(muxName, x, y, tooltip) {
   414→      const g = this._svg('g', {
   415→        class: 'multiplexer',
   416→        'data-mux': muxName
   417→      });
   418→
   419→      // Tooltip
   420→      const title = this._svg('title');
   421→      title.textContent = tooltip;
   422→      g.appendChild(title);
   423→
   424→      // Triangle pointing right (3 vertices)
   425→      const polygon = this._svg('polygon', {
   426→        points: `${x},${y - 10} ${x + 15},${y} ${x},${y + 10}`
   427→      });
   428→      g.appendChild(polygon);
   429→
   430→      return g;
   431→    }
   432→
   433→    /**
   434→     * Creates a pipeline register (red vertical bar with labels)
   435→     * @param {string} regName - Register name for data attributes (FD, DX, XM, MW)
   436→     * @param {number} x - X coordinate (left edge)
   437→     * @param {string} label - Display label (F/D, D/X, X/M, M/W)
   438→     * @param {string} tooltip - Tooltip description
   439→     * @returns {SVGGElement} Pipeline register group
   440→     * @private
   441→     */
   442→    _createPipelineRegister(regName, x, label, tooltip) {
   443→      const g = this._svg('g', {
   444→        class: 'pipeline-register',
   445→        'data-pipeline-reg': regName
   446→      });
   447→
   448→      // Tooltip
   449→      const title = this._svg('title');
   450→      title.textContent = tooltip;
   451→      g.appendChild(title);
   452→
   453→      // Vertical red bar
   454→      const bar = this._svg('rect', {
   455→        x: x,
   456→        y: 80,
   457→        width: 8,
   458→        height: 340,
   459→        rx: 2
   460→      });
   461→      g.appendChild(bar);
   462→
   463→      // Register label (above bar)
   464→      const labelText = this._svg('text', {
   465→        x: x + 4,
   466→        y: 65,
   467→        'text-anchor': 'middle',
   468→        class: 'pipeline-label'
   469→      });
   470→      labelText.textContent = label;
   471→      g.appendChild(labelText);
   472→
   473→      // Instruction display (below bar)
   474→      const instrText = this._svg('text', {
   475→        x: x + 4,
   476→        y: 440,
   477→        'text-anchor': 'middle',
   478→        class: 'pipeline-instruction',
   479→        'data-instruction-display': regName
   480→      });
   481→      instrText.textContent = 'NOP';
   482→      g.appendChild(instrText);
   483→
   484→      return g;
   485→    }
   486→
   487→    /**
   488→     * Renders the current CPU state
   489→     * Updates component highlighting and pipeline register instruction displays
   490→     * @param {CPUState} state - Current CPU state with pipeline data
   491→     */
   492→    render(state) {
   493→      // Clear all active states
   494→      this.svg.querySelectorAll('.component.active, .multiplexer.active')
   495→        .forEach(el => el.classList.remove('active'));
   496→
   497→      // Highlight active components based on pipeline stage
   498→      if (state.pipeline.IF.active) {
   499→        this.componentMap.get('IMEM')?.classList.add('active');
   500→        this.componentMap.get('PC')?.classList.add('active');
   501→      }
   502→
   503→      if (state.pipeline.ID.active) {
   504→        this.componentMap.get('REGFILE')?.classList.add('active');
   505→        this.componentMap.get('SIGNEXT')?.classList.add('active');
   506→      }
   507→
   508→      if (state.pipeline.EX.active) {
   509→        this.componentMap.get('ALU')?.classList.add('active');
   510→        this.componentMap.get('ALU_SRC')?.classList.add('active');
   511→      }
   512→
   513→      if (state.pipeline.MEM.active) {
   514→        // Only highlight data memory if actually reading or writing
   515→        if (state.pipeline.MEM.memRead || state.pipeline.MEM.memWrite) {
   516→          this.componentMap.get('DMEM')?.classList.add('active');
   517→        }
   518→      }
   519→
   520→      if (state.pipeline.WB.active) {
   521→        this.componentMap.get('WB_SRC')?.classList.add('active');
   522→      }
   523→
   524→      // Update pipeline register instruction displays
   525→      this._updatePipelineInstructions(state);
   526→    }
   527→
   528→    /**
   529→     * Updates instruction text in pipeline registers
   530→     * @param {CPUState} state - Current CPU state
   531→     * @private
   532→     */
   533→    _updatePipelineInstructions(state) {
   534→      // Map pipeline registers to their corresponding stages
   535→      const pipelineMap = {
   536→        'FD': 'IF',   // F/D shows what IF stage has
   537→        'DX': 'ID',   // D/X shows what ID stage has
   538→        'XM': 'EX',   // X/M shows what EX stage has
   539→        'MW': 'MEM'   // M/W shows what MEM stage has
   540→      };
   541→
   542→      Object.entries(pipelineMap).forEach(([regName, stageName]) => {
   543→        const displayEl = this.svg.querySelector(`[data-instruction-display="${regName}"]`);
   544→        if (!displayEl) return;
   545→
   546→        const stageData = state.pipeline[stageName];
   547→        if (stageData.active) {
   548→          // In non-pipelined mode, all stages share the same instruction
   549→          const instruction = state.pipeline.IF.instruction;
   550→          if (instruction) {
   551→            displayEl.textContent = `${instruction.mnemonic} ${this._formatInstruction(instruction)}`.trim();
   552→          } else {
   553→            displayEl.textContent = 'NOP';
   554→          }
   555→        } else {
   556→          displayEl.textContent = 'NOP';
   557→        }
   558→      });
   559→    }
   560→
   561→    /**
   562→     * Formats instruction operands for assembly-style display
   563→     * @param {object} instruction - Instruction object with mnemonic, type, and operand fields
   564→     * @returns {string} Formatted operand string
   565→     * @private
   566→     */
   567→    _formatInstruction(instruction) {
   568→      if (!instruction || instruction.mnemonic === 'NOP') {
   569→        return '';
   570→      }
   571→
   572→      const { type, rs, rt, rd, immediate } = instruction;
   573→
   574→      switch (type) {
   575→        case 'R':
   576→          // R-type: ADD $rd, $rs, $rt
   577→          return `$${rd}, $${rs}, $${rt}`;
   578→
   579→        case 'I':
   580→          if (instruction.mnemonic === 'ADDI') {
   581→            // ADDI $rt, $rs, imm
   582→            return `$${rt}, $${rs}, ${immediate}`;
   583→          } else if (instruction.mnemonic === 'LW') {
   584→            // LW $rt, imm($rs)
   585→            return `$${rt}, ${immediate}($${rs})`;
   586→          }
   587→          break;
   588→
   589→        case 'S':
   590→          // SW $rt, imm($rs)
   591→          return `$${rt}, ${immediate}($${rs})`;
   592→
   593→        case 'B':
   594→          // BEQ $rs, $rt, offset
   595→          return `$${rs}, $${rt}, ${immediate}`;
   596→
   597→        case 'J':
   598→          // J target
   599→          return `${immediate}`;
   600→
   601→        case 'NOP':
   602→          return '';
   603→
   604→        default:
   605→          return '';
   606→      }
   607→
   608→      return '';
   609→    }
   610→  }
   611→
   612→  // Export to global scope (vanilla JS pattern)
   613→  if (typeof window !== 'undefined') {
   614→    window.BlockDiagramView = BlockDiagramView;
   615→  } else if (typeof global !== 'undefined') {
   616→    global.BlockDiagramView = BlockDiagramView;
   617→  }
   618→})();
