    14→  --stage-if-color: #4CAF50;   /* Instruction Fetch - Green */
    15→  --stage-id-color: #2196F3;   /* Instruction Decode - Blue */
    16→  --stage-ex-color: #FF9800;   /* Execute - Orange */
    17→  --stage-mem-color: #9C27B0;  /* Memory Access - Purple */
    18→  --stage-wb-color: #F44336;   /* Write Back - Red */
    19→
    20→  /* Register change highlighting */
    21→  --color-highlight-yellow: #FFF9C4;
    22→}
    23→
    24→/* ============================================
    25→ * CPU VISUALIZER LAYOUT
    26→ * ============================================ */
    27→
    28→.cpu-visualizer {
    29→  display: flex;
    30→  flex-direction: column;
    31→  gap: 24px;
