/**
 * Updates ALU operation display based on current instruction
 * @param {CPUState} state - Current CPU state
 * @private
 */
_updateALUOperation(state) {
  const aluOpElement = this.svg.querySelector('[data-alu-op]');
  if (!aluOpElement) return;

  const instruction = state.pipeline.IF.instruction;
  if (!instruction || instruction.mnemonic === 'NOP') {
    aluOpElement.textContent = 'OP';
    return;
  }

  // Map instruction mnemonics to ALU operations
  const aluOpMap = {
    'ADD': 'ADD',
    'SUB': 'SUB',
    'AND': 'AND',
    'OR': 'OR',
    'ADDI': 'ADD',  // ADDI uses ALU ADD
    'LW': 'ADD',    // LW uses ALU to compute address (base + offset)
    'SW': 'ADD',    // SW uses ALU to compute address (base + offset)
    'BEQ': 'SUB',   // BEQ uses ALU subtraction for comparison
    'J': '',        // Jump doesn't use ALU
    'NOP': ''
  };

  const aluOp = aluOpMap[instruction.mnemonic] || 'OP';
  aluOpElement.textContent = aluOp;
}

