     1→/**
     2→ * BlockDiagramView - SVG-based processor block diagram visualization
     3→ *
     4→ * Renders a hardware-accurate 5-stage pipelined RISC processor architecture
     5→ * showing Instruction Memory, Register File, ALU, Data Memory, pipeline registers,
     6→ * multiplexers, PC, and data path connections.
     7→ *
     8→ * Components highlight based on active pipeline stages. Pipeline registers display
     9→ * current instruction names. Tooltips provide component descriptions.
    10→ *
    11→ * Usage:
    12→ *   const view = new BlockDiagramView(containerElement);
    13→ *   view.render(cpuState);
    14→ */
    15→(function() {
    16→  'use strict';
    17→
    18→  const SVG_NS = 'http://www.w3.org/2000/svg';
    19→
    20→  class BlockDiagramView {
    21→    /**
    22→     * Creates a BlockDiagramView instance
    23→     * @param {HTMLElement} container - DOM element to render SVG diagram into
    24→     */
    25→    constructor(container) {
    26→      this.container = container;
    27→      this.svg = null;
    28→      this.componentMap = new Map();  // Fast component lookup by data-component attribute
    29→      this.initializeDiagram();
    30→    }
    31→
    32→    /**
    33→     * Creates an SVG element with attributes
    34→     * @param {string} tagName - SVG element tag name
    35→     * @param {object} attributes - Attribute key-value pairs
    36→     * @returns {SVGElement} Created SVG element
    37→     * @private
    38→     */
    39→    _svg(tagName, attributes = {}) {
    40→      const element = document.createElementNS(SVG_NS, tagName);
    41→      Object.entries(attributes).forEach(([key, value]) => {
    42→        element.setAttribute(key, value);
    43→      });
    44→      return element;
    45→    }
    46→
    47→    /**
    48→     * Initializes the complete SVG block diagram
    49→     * Creates all components in painter's order (back to front)
    50→     * @private
    51→     */
    52→    initializeDiagram() {
    53→      // Create root SVG with responsive viewBox (expanded vertically for Control Unit at top)
    54→      this.svg = this._svg('svg', {
    55→        viewBox: '0 0 960 550',
    56→        preserveAspectRatio: 'xMidYMid meet',
    57→        class: 'cpu-block-diagram'
    58→      });
    59→
    60→      // Add stage labels (background layer)
    61→      this.svg.appendChild(this._createStageLabels());
    62→
    63→      // Add control lines (background layer - drawn first)
    64→      this.svg.appendChild(this._createControlLines());
    65→
    66→      // Add data path wires (background layer)
    67→      this.svg.appendChild(this._createDataPaths());
    68→
    69→      // Add hardware components (middle layer)
    70→      this.svg.appendChild(this._createControlUnit());
    71→      this.svg.appendChild(this._createIFStage());
    72→      this.svg.appendChild(this._createPipelineRegister('FD', 235, 'F/D', 'Fetch/Decode Register - Holds instruction between IF and ID stages'));
    73→      this.svg.appendChild(this._createIDStage());
    74→      this.svg.appendChild(this._createPipelineRegister('DX', 415, 'D/X', 'Decode/Execute Register - Holds decoded instruction and operands'));
    75→      this.svg.appendChild(this._createEXStage());
    76→      this.svg.appendChild(this._createPipelineRegister('XM', 575, 'X/M', 'Execute/Memory Register - Holds ALU result and write data'));
    77→      this.svg.appendChild(this._createMEMStage());
    78→      this.svg.appendChild(this._createPipelineRegister('MW', 735, 'M/W', 'Memory/Writeback Register - Holds data for register write'));
    79→      this.svg.appendChild(this._createWBStage());
    80→
    81→      // Append to container
    82→      this.container.appendChild(this.svg);
    83→    }
    84→
    85→    /**
    86→     * Creates stage labels above each pipeline stage
    87→     * @returns {SVGGElement} Group containing stage labels
    88→     * @private
    89→     */
    90→    _createStageLabels() {
    91→      const g = this._svg('g', { class: 'stage-labels' });
    92→
    93→      const stages = [
    94→        { label: 'IF', x: 85 },
    95→        { label: 'ID', x: 315 },
    96→        { label: 'EX', x: 490 },
    97→        { label: 'MEM', x: 665 },
    98→        { label: 'WB', x: 820 }
    99→      ];
   100→
   101→      stages.forEach(({ label, x }) => {
   102→        const text = this._svg('text', {
   103→          x: x,
   104→          y: 120,
   105→          class: 'stage-label-text'
   106→        });
   107→        text.textContent = label;
   108→        g.appendChild(text);
   109→      });
   110→
   111→      return g;
   112→    }
   113→
   114→    /**
   115→     * Creates Control Unit at top of diagram
   116→     * @returns {SVGGElement} Group containing Control Unit
   117→     * @private
   118→     */
   119→    _createControlUnit() {
   120→      const g = this._svg('g', { class: 'stage-group control-stage' });
   121→
   122→      // Control Unit block (centered at top)
   123→      const control = this._createComponent('CONTROL', 400, 40, 160, 50, 'Control', 'control-unit',
   124→        'Control Unit - Generates control signals based on instruction opcode (RegWrite, MemRead, MemWrite, ALUSrc, etc.)');
   125→      this.componentMap.set('CONTROL', control);
   126→      g.appendChild(control);
   127→
   128→      return g;
   129→    }
   130→
   131→    /**
   132→     * Creates control lines (dashed amber lines from Control Unit to components)
   133→     * @returns {SVGGElement} Group containing control signal wires
   134→     * @private
   135→     */
   136→    _createControlLines() {
   137→      const g = this._svg('g', { class: 'control-lines' });
   138→
   139→      // Control Unit to PC Source Mux
   140→      g.appendChild(this._svg('path', {
   141→        d: 'M 400 65 L 30 65 L 30 260',
   142→        class: 'control-line'
   143→      }));
   144→
   145→      // Control Unit to Register File (RegWrite)
   146→      g.appendChild(this._svg('path', {
   147→        d: 'M 430 90 L 430 110 L 330 110 L 330 130',
   148→        class: 'control-line'
   149→      }));
   150→
   151→      // Control Unit to ALU Src Mux
   152→      g.appendChild(this._svg('path', {
   153→        d: 'M 490 90 L 490 110 L 452 110 L 452 215',
   154→        class: 'control-line'
   155→      }));
   156→
   157→      // Control Unit to Data Memory (MemRead/MemWrite)
   158→      g.appendChild(this._svg('path', {
   159→        d: 'M 530 90 L 530 110 L 670 110 L 670 150',
   160→        class: 'control-line'
   161→      }));
   162→
   163→      // Control Unit to WB Src Mux
   164→      g.appendChild(this._svg('path', {
   165→        d: 'M 560 65 L 795 65 L 795 225',
   166→        class: 'control-line'
   167→      }));
   168→
   169→      return g;
   170→    }
   171→
   172→    /**
   173→     * Creates data path wires connecting components
   174→     * @returns {SVGGElement} Group containing all data path connections
   175→     * @private
   176→     */
   177→    _createDataPaths() {
   178→      const g = this._svg('g', { class: 'data-paths' });
   179→
   180→      // PC to Instruction Memory (horizontal)
   181→      g.appendChild(this._svg('path', {
   182→        d: 'M 80 280 H 100',
   183→        class: 'data-path'
   184→      }));
   185→
   186→      // Instruction Memory to F/D register (horizontal)
   187→      g.appendChild(this._svg('path', {
   188→        d: 'M 220 280 H 235',
   189→        class: 'data-path'
   190→      }));
   191→
   192→      // F/D to Register File (instruction decode) - orthogonal
   193→      g.appendChild(this._svg('path', {
   194→        d: 'M 243 240 H 260 V 200 H 270',
   195→        class: 'data-path'
   196→      }));
   197→
