   628→    /**
   629→     * Renders the current CPU state
   630→     * Updates component highlighting and pipeline register instruction displays
   631→     * @param {CPUState} state - Current CPU state with pipeline data
   632→     */
   633→    render(state) {
   634→      // Clear all active states
   635→      this.svg.querySelectorAll('.component.active, .multiplexer.active')
   636→        .forEach(el => el.classList.remove('active'));
   637→
   638→      // Highlight active components based on pipeline stage
   639→      if (state.pipeline.IF.active) {
   640→        this.componentMap.get('IMEM')?.classList.add('active');
   641→        this.componentMap.get('PC')?.classList.add('active');
   642→        this.componentMap.get('PC_SRC')?.classList.add('active');
   643→      }
   644→
   645→      if (state.pipeline.ID.active) {
   646→        this.componentMap.get('REGFILE')?.classList.add('active');
   647→        this.componentMap.get('SIGNEXT')?.classList.add('active');
   648→        this.componentMap.get('CONTROL')?.classList.add('active');
   649→      }
   650→
   651→      if (state.pipeline.EX.active) {
   652→        this.componentMap.get('ALU')?.classList.add('active');
   653→        this.componentMap.get('ALU_SRC')?.classList.add('active');
   654→        this.componentMap.get('BRANCH_ADD')?.classList.add('active');
   655→
   656→        // Update ALU operation text
   657→        this._updateALUOperation(state);
   658→      }
   659→
   660→      if (state.pipeline.MEM.active) {
   661→        // Only highlight data memory if actually reading or writing
   662→        if (state.pipeline.MEM.memRead || state.pipeline.MEM.memWrite) {
   663→          this.componentMap.get('DMEM')?.classList.add('active');
   664→        }
   665→      }
   666→
   667→      if (state.pipeline.WB.active) {
   668→        this.componentMap.get('WB_SRC')?.classList.add('active');
   669→      }
   670→
   671→      // Update pipeline register instruction displays
   672→      this._updatePipelineInstructions(state);
   673→    }
