   675→    /**
   676→     * Updates ALU operation display based on current instruction
   677→     * @param {CPUState} state - Current CPU state
   678→     * @private
   679→     */
   680→    _updateALUOperation(state) {
   681→      const aluOpElement = this.svg.querySelector('[data-alu-op]');
   682→      if (!aluOpElement) return;
   683→
   684→      const instruction = state.pipeline.IF.instruction;
   685→      if (!instruction || instruction.mnemonic === 'NOP') {
   686→        aluOpElement.textContent = 'OP';
   687→        return;
   688→      }
   689→
   690→      // Map instruction mnemonics to ALU operations
   691→      const aluOpMap = {
   692→        'ADD': 'ADD',
   693→        'SUB': 'SUB',
   694→        'AND': 'AND',
   695→        'OR': 'OR',
   696→        'ADDI': 'ADD',  // ADDI uses ALU ADD
   697→        'LW': 'ADD',    // LW uses ALU to compute address (base + offset)
   698→        'SW': 'ADD',    // SW uses ALU to compute address (base + offset)
   699→        'BEQ': 'SUB',   // BEQ uses ALU subtraction for comparison
   700→        'J': '',        // Jump doesn't use ALU
   701→        'NOP': ''
   702→      };
   703→
   704→      const aluOp = aluOpMap[instruction.mnemonic] || 'OP';
   705→      aluOpElement.textContent = aluOp;
   706→    }
   707→
   708→    /**
   709→     * Updates instruction text in pipeline registers
   710→     * @param {CPUState} state - Current CPU state
   711→     * @private
   712→     */
   713→    _updatePipelineInstructions(state) {
   714→      // Map pipeline registers to their corresponding stages
   715→      const pipelineMap = {
   716→        'FD': 'IF',   // F/D shows what IF stage has
   717→        'DX': 'ID',   // D/X shows what ID stage has
   718→        'XM': 'EX',   // X/M shows what EX stage has
   719→        'MW': 'MEM'   // M/W shows what MEM stage has
   720→      };
   721→
   722→      Object.entries(pipelineMap).forEach(([regName, stageName]) => {
   723→        const displayEl = this.svg.querySelector(`[data-instruction-display="${regName}"]`);
   724→        if (!displayEl) return;
   725→
   726→        const stageData = state.pipeline[stageName];
   727→        if (stageData.active) {
   728→          // In non-pipelined mode, all stages share the same instruction
   729→          const instruction = state.pipeline.IF.instruction;
   730→          if (instruction) {
   731→            displayEl.textContent = `${instruction.mnemonic} ${this._formatInstruction(instruction)}`.trim();
   732→          } else {
   733→            displayEl.textContent = 'NOP';
   734→          }
   735→        } else {
   736→          displayEl.textContent = 'NOP';
   737→        }
   738→      });
   739→    }
   740→
   741→    /**
   742→     * Formats instruction operands for assembly-style display
   743→     * @param {object} instruction - Instruction object with mnemonic, type, and operand fields
   744→     * @returns {string} Formatted operand string
   745→     * @private
   746→     */
   747→    _formatInstruction(instruction) {
   748→      if (!instruction || instruction.mnemonic === 'NOP') {
   749→        return '';
   750→      }
   751→
   752→      const { type, rs, rt, rd, immediate } = instruction;
   753→
   754→      switch (type) {
   755→        case 'R':
   756→          // R-type: ADD $rd, $rs, $rt
   757→          return `$${rd}, $${rs}, $${rt}`;
   758→
   759→        case 'I':
   760→          if (instruction.mnemonic === 'ADDI') {
   761→            // ADDI $rt, $rs, imm
   762→            return `$${rt}, $${rs}, ${immediate}`;
   763→          } else if (instruction.mnemonic === 'LW') {
   764→            // LW $rt, imm($rs)
   765→            return `$${rt}, ${immediate}($${rs})`;
   766→          }
   767→          break;
   768→
   769→        case 'S':
   770→          // SW $rt, imm($rs)
   771→          return `$${rt}, ${immediate}($${rs})`;
   772→
   773→        case 'B':
   774→          // BEQ $rs, $rt, offset
   775→          return `$${rs}, $${rt}, ${immediate}`;
   776→
   777→        case 'J':
   778→          // J target
   779→          return `${immediate}`;
   780→
   781→        case 'NOP':
   782→          return '';
   783→
   784→        default:
   785→          return '';
   786→      }
   787→
   788→      return '';
   789→    }
   790→  }
   791→
   792→  // Export to global scope (vanilla JS pattern)
   793→  if (typeof window !== 'undefined') {
   794→    window.BlockDiagramView = BlockDiagramView;
   795→  } else if (typeof global !== 'undefined') {
   796→    global.BlockDiagramView = BlockDiagramView;
