/**
 * Creates data path wires connecting components
 * @returns {SVGGElement} Group containing all data path connections
 * @private
 */
_createDataPaths() {
  const g = this._svg('g', { class: 'data-paths' });

  // Helper to create path with tooltip and stage info
  const createWire = (d, tooltip, stage, wireId) => {
    const path = this._svg('path', {
      d: d,
      class: 'data-path',
      'data-wire': wireId,
      'data-stage': stage
    });
    const title = this._svg('title');
    title.textContent = tooltip;
    path.appendChild(title);
    return path;
  };

  // PC to Instruction Memory (horizontal)
  g.appendChild(createWire(
    'M 80 280 H 100',
    'PC Address - Current instruction address to Instruction Memory',
    'IF',
    'pc-to-imem'
  ));

  // Instruction Memory to F/D register (horizontal)
  g.appendChild(createWire(
    'M 220 280 H 235',
    'Instruction [32] - Fetched instruction word',
    'IF',
    'imem-to-fd'
  ));

  // F/D to Register File (instruction decode) - orthogonal
  const fdToReg = createWire(
    'M 243 240 H 260 V 200 H 270',
    'rs [5] - Source register 1 address',
    'ID',
    'fd-to-regfile-rs'
  );
  g.appendChild(fdToReg);
  // Add bit-width annotation for 5-bit address
  const rsAnnotation = this._svg('text', {
    x: 255,
    y: 225,
    class: 'bit-width'
  });
  rsAnnotation.textContent = '5';
  g.appendChild(rsAnnotation);

  // F/D to Register File (rt address - second decode path)
  const fdToRegRt = createWire(
    'M 243 290 H 270',
    'rt [5] - Source register 2 address / destination for I-type',
    'ID',
    'fd-to-regfile-rt'
  );
  g.appendChild(fdToRegRt);
  // Add bit-width annotation for 5-bit address
  const rtAnnotation = this._svg('text', {
    x: 255,
    y: 303,
    class: 'bit-width'
  });
  rtAnnotation.textContent = '5';
  g.appendChild(rtAnnotation);

  // F/D to Sign Extend - orthogonal
  const fdToSignExt = createWire(
    'M 243 437 H 290',
    'Immediate [16] - Immediate field for sign extension',
    'ID',
    'fd-to-signext'
  );
  g.appendChild(fdToSignExt);
  // Add bit-width annotation for 16-bit immediate
  const immAnnotation = this._svg('text', {
    x: 265,
    y: 450,
    class: 'bit-width'
  });
  immAnnotation.textContent = '16';
  g.appendChild(immAnnotation);

  // Register File to D/X register (read data 1) - horizontal
  g.appendChild(createWire(
    'M 390 220 H 415',
    'Read Data 1 [32] - Value from register rs',
    'ID',
    'regfile-to-dx-rd1'
  ));

  // Register File to D/X register (read data 2) - horizontal
  g.appendChild(createWire(
    'M 390 260 H 415',
    'Read Data 2 [32] - Value from register rt',
    'ID',
    'regfile-to-dx-rd2'
  ));

  // Sign Extend to D/X register - horizontal
  g.appendChild(createWire(
    'M 370 437 H 415',
    'Sign Extended [32] - 32-bit sign-extended immediate',
    'ID',
    'signext-to-dx'
  ));

  // Sign Extend to Branch Target Adder - new connection
  g.appendChild(createWire(
    'M 330 420 V 390 H 410 V 380',
    'Sign Extended Offset [32] - Branch offset for target calculation',
    'ID',
    'signext-to-branchadd'
  ));

  // PC+4 to Branch Target Adder - new connection
  g.appendChild(createWire(
    'M 50 350 H 90 V 390 H 430 V 380',
    'PC+4 [32] - Sequential address for branch target calculation',
    'EX',
    'pc4-to-branchadd'
  ));

  // Branch Target Adder to PC Source Mux - new connection
  g.appendChild(createWire(
    'M 420 340 V 320 H 90 V 280 H 45 V 275',
    'Branch Target [32] - Computed branch destination address',
    'EX',
    'branchadd-to-pcmux'
  ));

  // D/X to ALU Src Mux - orthogonal
  g.appendChild(createWire(
    'M 423 270 H 445',
    'ALU Input A [32] - First ALU operand from register',
    'EX',
    'dx-to-alumux'
  ));

  // ALU Src Mux to ALU - horizontal
  this.aluMuxToAluWire = createWire(
    'M 460 270 H 480',
    'ALU Input B [32] - Second ALU operand (register or immediate)',
    'EX',
    'alumux-to-alu'
  );
  g.appendChild(this.aluMuxToAluWire);

  // ALU to X/M register - horizontal
  g.appendChild(createWire(
    'M 560 270 H 575',
    'ALU Result [32] - Computation result',
    'EX',
    'alu-to-xm'
  ));

  // X/M to Data Memory (address) - orthogonal
  g.appendChild(createWire(
    'M 583 260 H 610',
    'Memory Address [32] - Address for load/store',
    'MEM',
    'xm-to-dmem-addr'
  ));

  // X/M to Data Memory (write data) - orthogonal
  g.appendChild(createWire(
    'M 583 290 H 610',
    'Write Data [32] - Data to store in memory',
    'MEM',
    'xm-to-dmem-data'
  ));

  // Data Memory to M/W register - horizontal
  g.appendChild(createWire(
    'M 730 280 H 735',
    'Read Data [32] - Data loaded from memory',
    'MEM',
    'dmem-to-mw'
  ));

  // M/W to WB Mux - horizontal
  g.appendChild(createWire(
    'M 743 280 H 780',
    'Memory/ALU Data [32] - Data for register writeback',
    'WB',
    'mw-to-wbmux'
  ));

  // WB Mux to Register File (write back - long feedback line) - Manhattan routing
  const wbToReg = createWire(
    'M 810 280 H 850 V 150 H 330 V 170',
    'Write Data [32] - Data written back to register file',
    'WB',
    'wbmux-to-regfile'
  );
  wbToReg.setAttribute('fill', 'none');
  g.appendChild(wbToReg);
  // Add bit-width annotation for write address (5-bit)
  const wAddrAnnotation = this._svg('text', {
    x: 335,
    y: 160,
    class: 'bit-width'
  });
  wAddrAnnotation.textContent = '5';
  g.appendChild(wAddrAnnotation);

  // PC +4 feedback (Adder to PC Source Mux) - Manhattan routing
  const pc4Feedback = createWire(
    'M 50 350 H 70 V 370 H 10 V 265 H 35',
    'PC+4 [32] - Next sequential instruction address',
    'IF',
    'pc4-feedback'
  );
  pc4Feedback.setAttribute('fill', 'none');
  g.appendChild(pc4Feedback);

  // PC Source Mux to PC input
  this.pcMuxToPcWire = createWire(
    'M 35 280 H 20 V 280',
    'Selected PC [32] - Next program counter value',
    'IF',
    'pcmux-to-pc'
  );
  g.appendChild(this.pcMuxToPcWire);

  return g;
}

